const crypto = require('crypto');
const input = $input.first().json;
const headers = input.headers || {};
const timestamp = headers['x-abap-timestamp'];
const eventId = headers['x-abap-event-id'];
const signature = headers['x-abap-signature'];
const body = input.body;
if (!Number.isSafeInteger(Number(timestamp)) || !eventId || !signature || !body) throw new Error('Invalid ABAP webhook headers.');
const canonical = JSON.stringify(body);
const signed = ['abap.webhook.v1', timestamp, eventId, canonical].join('\n');
const expected = 'v1=' + crypto.createHmac('sha256', $env.ABAP_OUTBOUND_WEBHOOK_SECRET).update(signed).digest('hex');
if (expected.length !== signature.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature))) throw new Error('ABAP webhook signature rejected.');
if (body.schema_version !== 'abap.webhook.v1' || body.event_type !== 'workflow.execution.started' || Object.keys(body.data || {}).sort().join(',') !== 'execution_id,trigger_type,workflow_id' || body.data.trigger_type !== 'schedule') throw new Error('ABAP webhook shape rejected.');
const execution_id = body.data.execution_id;
const workflow_id = body.data.workflow_id;
return [{ json: { execution_id, workflow_id, provider_body: JSON.stringify({ execution_id, workflow_id }) } }];

const crypto = require('crypto');
const executionId = $('Verify signed ABAP request').first().json.execution_id;
const now = Math.floor(Date.now() / 1000);
const eventId = crypto.randomUUID();
const body = JSON.stringify({ correlation_id: executionId, data: { status: 'completed' }, event_id: eventId, event_type: 'workflow.execution.result', occurred_at: new Date(now * 1000).toISOString(), schema_version: 'abap.webhook.v1' });
const signed = ['abap.webhook.v1', String(now), eventId, body].join('\n');
const signature = 'v1=' + crypto.createHmac('sha256', $env.ABAP_INBOUND_WEBHOOK_SECRET).update(signed).digest('hex');
return [{ json: { body, headers: { 'Content-Type': 'application/json', 'X-ABAP-Timestamp': String(now), 'X-ABAP-Event-Id': eventId, 'X-ABAP-Signature': signature } } }];
